// Shapes of the static world data shipped with the game (generated by tools/build-world-data.ts).

export type AirportSize = 'large' | 'medium' | 'small';
export type RunwaySurface = 'hard' | 'soft' | 'unknown';

export interface Runway {
  /** Runway designators, e.g. "11/29" */
  ends: string;
  lengthM: number;
  widthM: number | null;
  surface: RunwaySurface;
}

export interface Airport {
  /** Stable game id = OurAirports ident (usually the ICAO code, e.g. "LOWW") */
  id: string;
  iata: string | null;
  icao: string | null;
  name: string;
  city: string;
  /** ISO 3166-1 alpha-2 country code, e.g. "AT" */
  country: string;
  lat: number;
  lon: number;
  elevationFt: number | null;
  size: AirportSize;
  /** IANA time zone, e.g. "Europe/Vienna" */
  tz: string;
  runways: Runway[];
  /** Longest usable runway in metres (0 if unknown) */
  longestRunwayM: number;
  /** People living in cities (≥15,000 inhabitants) within 100 km — a first measure of the catchment area */
  catchmentPop: number;
}

export interface Country {
  code: string;
  /** English name; the UI shows a translated name via Intl.DisplayNames when available */
  name: string;
  continent: string;
  gdpPerCapitaUsd: number | null;
  gdpYear: number | null;
  tourismArrivals: number | null;
  tourismYear: number | null;
}

export interface WorldData {
  airports: Airport[];
  countries: Record<string, Country>;
  meta: { generated: string; sources: string[] };
}
